// Every line of corpus/expected.txt names a raw input and the exact outcome `runOne` must give.
test "fuzz corpus expectations" {
    const gpa = std.testing.allocator;
    const io = std.testing.io;
    const cwd = std.Io.Dir.cwd();
    const text = try cwd.readFileAlloc(io, corpus_root ++ "/expected.txt", gpa, .limited(1 << 20));
    defer gpa.free(text);
    var lines = std.mem.splitScalar(u8, text, '\n');
    while (lines.next()) |raw_line| {
        const line = std.mem.trim(u8, raw_line, " \t\r");
        if (line.len == 0 or line[0] == '#') continue;
        var fields = std.mem.tokenizeAny(u8, line, " \t");
        const path = fields.next() orelse continue;
        const want = fields.next() orelse return error.BadExpectation;
        const slash = std.mem.indexOfScalar(u8, path, '/') orelse return error.BadExpectation;
        const target = std.meta.stringToEnum(Target, path[0..slash]) orelse return error.BadExpectation;
        const full = try std.fs.path.join(gpa, &.{ corpus_root, path });
        defer gpa.free(full);
        const bytes = try cwd.readFileAlloc(io, full, gpa, .limited(max_input_len));
        defer gpa.free(bytes);
        const fb = runOne(target, gpa, bytes);
        const ok = if (std.mem.eql(u8, want, "ok"))
            fb.err == null
        else if (std.mem.eql(u8, want, "error"))
            fb.err != null
        else if (std.mem.startsWith(u8, want, "error."))
            if (fb.err) |e| std.mem.eql(u8, @errorName(e), want["error.".len..]) else false
        else
            return error.BadExpectation;
        if (!ok) {
            std.debug.print("expected.txt: {s}: wanted {s}, got {s}\n", .{ path, want, if (fb.err) |e| @errorName(e) else "ok" });
            return error.UnexpectedOutcome;
        }
    }
}
//! Shared fuzz helpers.
const std = @import("std");

/// Fuzz decisions read from the input. Exhausted input yields zeros, so a shorter
/// input is always a smaller case: truncating is our shrinker.
pub const Input = struct {
    bytes: []const u8,
    pos: usize = 0,

    pub fn byte(in: *Input) u8 {
        if (in.pos >= in.bytes.len) return 0;
        defer in.pos += 1;
        return in.bytes[in.pos];
    }
    /// In [0, n); 0 when n == 0.
    pub fn below(in: *Input, n: usize) usize {
        if (n == 0) return 0;
        return (@as(usize, in.byte()) | @as(usize, in.byte()) << 8) % n;
    }
    /// Little-endian, zero-padded past the end.
    pub fn int(in: *Input, comptime T: type) T {
        var buf: [@sizeOf(T)]u8 = @splat(0);
        for (&buf) |*b| b.* = in.byte();
        return std.mem.readInt(T, &buf, .little);
    }
    pub fn rest(in: *Input) []const u8 {
        const r = in.bytes[@min(in.pos, in.bytes.len)..];
        in.pos = in.bytes.len;
        return r;
    }
};

/// What one execution looked like; a new `sig` grows the run loop's corpus.
pub const Feedback = struct {
    err: ?anyerror = null,
    rows: u64 = 0,
    detail: u64 = 0, // target-specific bits (encodings seen, reader modes that succeeded, ...)

    pub fn sig(f: Feedback) u64 {
        var h = std.hash.Wyhash.init(0);
        h.update(if (f.err) |e| @errorName(e) else "ok");
        h.update(std.mem.asBytes(&@min(f.rows, 8)));
        h.update(std.mem.asBytes(&f.detail));
        return h.final();
    }
};
