    // Default to RLE encoding for backwards compatibility
    return decodeColumnDynamicWithEncoding(
        allocator,
        schema_elem,
        value_data,
        num_values,
        max_def_level,
        max_rep_level,
        uses_dict,
        string_dict,
        int32_dict,
        int64_dict,
        null,
        null,
        null,
        null,
        .rle,
        .rle,
    );
}

